                                </div>
                              )}
                            </td>
                            <td style={{padding:'16px 20px',textAlign:'right'}}>
                              <div style={{display:'flex',justifyContent:'flex-end',gap:8}}>
                                {!isSA && (
                                  <>
                                    {/* Super Admin Role Control Buttons */}
